/// The driver app's parsing of the ride lifecycle, against the server's own
/// captured responses.
///
/// WHY
/// ---
/// Authentication was pinned to a generated contract after this app shipped
/// reading `data['access']` for a field the server calls `token` -- a login
/// that could never work, with tests that agreed with the app because they
/// were fixtures written from the same wrong assumption. Everything after
/// login had the same exposure and no such pin.
///
/// `test/contracts/ride_contracts.json` is generated by
/// `tests/test_ride_contract_capture.py` from real view output.
///
/// Regenerate:
///   cd SaaradhiGo-backend && pytest tests/test_ride_contract_capture.py
///   cp contracts/ride_contracts.json ../SaaradhiGo-driver/test/contracts/
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:saaradhigo_driver/domain/models/trip_model.dart';

Map<String, dynamic> _contract() {
  final file = File('test/contracts/ride_contracts.json');
  if (!file.existsSync()) {
    fail(
      'test/contracts/ride_contracts.json is missing. Regenerate it with '
      'tests/test_ride_contract_capture.py in the backend.',
    );
  }
  return jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
}

Map<String, dynamic> _endpoint(String name) {
  final endpoints = _contract()['endpoints'] as Map<String, dynamic>;
  final entry = endpoints[name];
  if (entry == null) {
    fail(
      'The contract has no "$name". Captured: '
      '${endpoints.keys.join(", ")}',
    );
  }
  return (entry as Map).cast<String, dynamic>();
}

Map<String, dynamic> _data(String name) =>
    ((_endpoint(name)['body'] as Map)['data'] as Map).cast<String, dynamic>();

void main() {
  group('the contract file', () {
    test('exists and names its generator', () {
      expect(_contract()['_README'], contains('GENERATED'));
    });
  });

  group('the trip status vocabulary', () {
    test('every status the server can send decodes to its OWN enum value', () {
      // This is the test that matters, and it is not the same as "the enum
      // has six values".
      //
      // TripModel's generated decoder ends in `?? TripStatus.requested`, so
      // an unrecognised status does not throw -- it silently becomes
      // `requested`. That is worse than blank: an in-progress trip would be
      // presented to a driver as a brand-new one, and `isActive` would still
      // be true so the session would stay open.
      //
      // Asserting each code maps to a DISTINCT value means a status added
      // server-side fails here instead of being absorbed by the fallback.
      final vocabulary = (_contract()['trip_status_vocabulary'] as List)
          .cast<String>();
      expect(vocabulary, isNotEmpty);

      final decoded = <String, TripStatus>{};
      for (final code in vocabulary) {
        final trip = TripModel.fromJson({'id': 1, 'status': code});
        decoded[code] = trip.status;
      }

      // No two codes may share an enum value, and only 'requested' may be
      // 'requested' -- anything else landing there is the fallback firing.
      for (final entry in decoded.entries) {
        if (entry.key == 'requested') continue;
        expect(
          entry.value,
          isNot(TripStatus.requested),
          reason:
              'the server sends "${entry.key}" and this app decoded it '
              'as `requested` -- the unknown-value fallback absorbed it, so '
              'a driver would see the wrong stage of the trip',
        );
      }
      expect(
        decoded.values.toSet().length,
        vocabulary.length,
        reason: 'two server statuses collapsed into one app state: $decoded',
      );
    });

    test('terminal statuses are the ones that close the session', () {
      expect(
        TripModel.fromJson({'id': 1, 'status': 'completed'}).status.isTerminal,
        isTrue,
      );
      expect(
        TripModel.fromJson({'id': 1, 'status': 'cancelled'}).status.isTerminal,
        isTrue,
      );
      for (final live in ['requested', 'accepted', 'reached', 'in_progress']) {
        expect(
          TripModel.fromJson({'id': 1, 'status': live}).status.isTerminal,
          isFalse,
          reason: '"$live" is a live trip and must keep the session open',
        );
      }
    });
  });

  group('the trip record the server really sends', () {
    test('TripModel parses it without throwing', () {
      // The whole point: this app's own decoder, on the server's own bytes.
      final data = _data('ride_trip_detail_driver');

      expect(() => TripModel.fromJson(data), returnsNormally);
    });

    test('the fields the driver screens read survive the parse', () {
      final trip = TripModel.fromJson(_data('ride_trip_detail_driver'));

      expect(trip.id, greaterThan(0));
      expect(trip.status, isNotNull);
      expect(
        trip.pickupAddress,
        isNotNull,
        reason: 'the driver needs somewhere to go',
      );
      expect(trip.destinationAddress, isNotNull);
    });

    test('the coordinates parse as numbers, whatever they arrive as', () {
      // The server serialises Decimal coordinates as strings. A silent null
      // here puts a driver on a map with no pickup pin.
      final trip = TripModel.fromJson(_data('ride_trip_detail_driver'));

      expect(trip.pickupLat, isNotNull);
      expect(trip.pickupLng, isNotNull);
      expect(trip.pickupLat, isA<double>());
    });

    test(
      'an unrelated rider is refused, and the app sees an error envelope',
      () {
        final entry = _endpoint('ride_trip_detail_denied_other_rider');

        expect(entry['status_code'], anyOf(403, 404));
        expect((entry['body'] as Map)['status'], 'error');
      },
    );
  });

  group('driver history', () {
    test('is paginated under the names the app pages with', () {
      final data = _data('ride_history_driver');

      expect(data.containsKey('results'), isTrue);
      expect(data.containsKey('count'), isTrue);
      expect(data.containsKey('next'), isTrue);
    });
  });

  group('earnings and withdrawals', () {
    test('the earnings summary carries the figures the screen shows', () {
      final data = _data('driver_earnings_summary');

      for (final field in [
        'today_earned',
        'today_trips',
        'total_earned',
        'total_net',
        'commission_percent',
      ]) {
        expect(
          data.containsKey(field),
          isTrue,
          reason: 'the earnings summary has no "$field"',
        );
      }
    });

    test('net and gross are both present, and are different things', () {
      // A driver shown gross as though it were take-home is a support
      // ticket at best.
      final data = _data('driver_earnings_summary');

      expect(data.containsKey('today_earned'), isTrue);
      expect(data.containsKey('today_net'), isTrue);
      expect(data.containsKey('total_commission'), isTrue);
    });

    test('the withdrawal balance carries its own gating fields', () {
      final data = _data('driver_withdrawal_balance');

      for (final field in [
        'available_balance',
        'minimum_withdrawal',
        'blocked',
      ]) {
        expect(
          data.containsKey(field),
          isTrue,
          reason: 'withdrawal balance has no "$field"; the UI gates on it',
        );
      }
    });
  });

  group('incentives and elite status', () {
    test('incentives come back as a list', () {
      final body = (_endpoint('driver_incentives')['body'] as Map)
          .cast<String, dynamic>();

      expect(
        body['data'],
        isA<List>(),
        reason: 'the app maps over this directly',
      );
    });

    test(
      'the incentives route is the doubled path, as the server serves it',
      () {
        // servers/driver/urls.py is included at /driver/ and declares
        // path('driver/incentives/'), so the real route has the segment twice.
        // The app used to try the single-segment path first and retry on 404.
        expect(
          _endpoint('driver_incentives')['note'],
          contains('/driver/driver/incentives/'),
        );
      },
    );

    test('elite status carries the qualification fields', () {
      final data = _data('driver_elite_status');

      for (final field in [
        'tier',
        'total_trips',
        'rating',
        'acceptance_rate',
        'cancellation_rate',
      ]) {
        expect(
          data.containsKey(field),
          isTrue,
          reason: 'elite status has no "$field"',
        );
      }
    });
  });

  group('nothing in these envelopes leaks what it should not', () {
    test('no payload carries a password, a refresh token or an FCM token', () {
      final endpoints = _contract()['endpoints'] as Map<String, dynamic>;

      for (final entry in endpoints.entries) {
        final text = jsonEncode(entry.value).toLowerCase();
        for (final leak in ['password', 'fcm_token', 'refresh_token']) {
          expect(
            text.contains(leak),
            isFalse,
            reason: '${entry.key} carries "$leak"',
          );
        }
      }
    });
  });
}
